INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7103148, 1082799, 77196, '<td valign="top">Love the car. The top of the convertible top and the roof eaves are competing for the horizontal line. Shooting op cars is not as easy as one would think.</td>', 'Love the car. The top of the convertible top and the roof eaves are competing for the horizontal line. Shooting op cars is not as easy as one would think.', '2013-09-16 01:07:49.000000', NULL, 1),
(7103151, 1082979, 77196, '<td valign="top">Love the trace of whipped cream by her mouth.</td>', 'Love the trace of whipped cream by her mouth.', '2013-09-16 01:08:58.000000', NULL, 1),
(7103153, 1082575, 77196, '<td valign="top">The processing makes the raspberries in the center and some of the strawberries look metallic. Very nice colors, lighting, and arrangement.</td>', 'The processing makes the raspberries in the center and some of the strawberries look metallic. Very nice colors, lighting, and arrangement.', '2013-09-16 01:10:27.000000', NULL, 1),
(7103156, 1082978, 77196, '<td valign="top">IMO this has some issues that seriously detract from the image. The far side of the water acts as a horizon line in the image and it isn''t level. The leaves and foliage on the far side of the water compete with the ducks for attention. The lighting is ok on near ducks, but the ducks still in the water look blown out. White water birds are very though to get lighting right on.<br/>If you crop off part of the leftmost duck, you should also crop off part of the rightmost one for symmetry. <br/>The different poses are priceless and well captured. Nice color on the beaks and feet.</td>', 'IMO this has some issues that seriously detract from the image. The far side of the water acts as a horizon line in the image and it isn''t level. The leaves and foliage on the far side of the water compete with the ducks for attention. The lighting is ok on near ducks, but the ducks still in the water look blown out. White water birds are very though to get lighting right on.If you crop off part of the leftmost duck, you should also crop off part of the rightmost one for symmetry. The different poses are priceless and well captured. Nice color on the beaks and feet.', '2013-09-16 01:17:58.000000', NULL, 1),
(7103157, 1083069, 30861, '<td valign="top">Beata? Do you need a loan?</td>', 'Beata? Do you need a loan?', '2013-09-16 01:18:14.000000', NULL, 1),
(7103158, 1083001, 77196, '<td valign="top">Wonderful colors!</td>', 'Wonderful colors!', '2013-09-16 01:18:34.000000', NULL, 1),
(7103159, 1083070, 77196, '<td valign="top">Love black, white, and red. Very nicely done. When can I open them?</td>', 'Love black, white, and red. Very nicely done. When can I open them?', '2013-09-16 01:19:20.000000', NULL, 1),
(7103160, 1083058, 77196, '<td valign="top">Great concept and nicely done. It would help to clone out or blemish fix the spots on the table. Especially in front of and at the back edge to the left of the corks.</td>', 'Great concept and nicely done. It would help to clone out or blemish fix the spots on the table. Especially in front of and at the back edge to the left of the corks.', '2013-09-16 01:21:22.000000', NULL, 1),
(7103161, 1082925, 77196, '<td valign="top">Great image. Love the dirty white and blue contrast. Really like the window decorations. Not clear how this relates to 9.</td>', 'Great image. Love the dirty white and blue contrast. Really like the window decorations. Not clear how this relates to 9.', '2013-09-16 01:24:01.000000', NULL, 1),
(7103162, 1082967, 77196, '<td valign="top">Nice framing. Like the sepia toning. Works well in this image.</td>', 'Nice framing. Like the sepia toning. Works well in this image.', '2013-09-16 01:24:49.000000', NULL, 1),
(7103165, 1082933, 77196, '<td valign="top">Sorry. Missed me with this one. Not sure how it relates to 9. Text isn''t level. Not sure why you didn''t crop off the grass on the left side. The lichens add some interest.</td>', 'Sorry. Missed me with this one. Not sure how it relates to 9. Text isn''t level. Not sure why you didn''t crop off the grass on the left side. The lichens add some interest.', '2013-09-16 01:30:39.000000', NULL, 1),
(7103166, 1083036, 77196, '<td valign="top">Great image of the lady bug about to fly away. Not really a fan of reducing the background children to colored blobs.</td>', 'Great image of the lady bug about to fly away. Not really a fan of reducing the background children to colored blobs.', '2013-09-16 01:32:20.000000', NULL, 1),
(7103168, 1082969, 77196, '<td valign="top">IMO this would have benefitted from a bit larger dof, like 2 lobsters worth.</td>', 'IMO this would have benefitted from a bit larger dof, like 2 lobsters worth.', '2013-09-16 01:33:36.000000', NULL, 1),
(7103169, 1082868, 77196, '<td valign="top">Absolutely love the wood grain on the dock. Nice lighting and color.</td>', 'Absolutely love the wood grain on the dock. Nice lighting and color.', '2013-09-16 01:34:26.000000', NULL, 1),
(7103170, 1083050, 77196, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2013-09-16 01:35:17.000000', NULL, 1),
