(7103172, 1082927, 77196, '<td valign="top">Definitely some mind bending perspective going on here. Nicely captured. Maybe a tad too busy. Scaffolding doesn''t help.</td>', 'Definitely some mind bending perspective going on here. Nicely captured. Maybe a tad too busy. Scaffolding doesn''t help.', '2013-09-16 01:38:38.000000', NULL, 1),
(7103173, 1082924, 77196, '<td valign="top">Yum! Fried worm! Aesthetically not terribly pleasing, but interesting echo in stain on concrete.</td>', 'Yum! Fried worm! Aesthetically not terribly pleasing, but interesting echo in stain on concrete.', '2013-09-16 01:40:10.000000', NULL, 1),
(7103174, 1083062, 77196, '<td valign="top">Interesting, but not sure what its saying. Nicely done. Looks to not be easy with the lights, background and glass.</td>', 'Interesting, but not sure what its saying. Nicely done. Looks to not be easy with the lights, background and glass.', '2013-09-16 01:41:33.000000', NULL, 1),
(7103176, 1083027, 77196, '<td valign="top">Oh come on! I know ants are strong, but it is a bit much to expect me to believe it tied the vine to look like a nine! Very nicely captured with very nice focus and booked. Slightly Oof at leaf at top of nine.</td>', 'Oh come on! I know ants are strong, but it is a bit much to expect me to believe it tied the vine to look like a nine! Very nicely captured with very nice focus and booked. Slightly Oof at leaf at top of nine.', '2013-09-16 01:43:52.000000', NULL, 1),
(7103209, 1082967, 28742, '<td valign="top">I am appropriately giving you a nine. :) Fantastic.</td>', 'I am appropriately giving you a nine. :) Fantastic.', '2013-09-16 03:19:43.000000', NULL, 1),
(7103245, 1083027, 109387, '<td valign="top">By far the best one in the challenge. Great natural number, colors, bokeh and perfect focus.</td>', 'By far the best one in the challenge. Great natural number, colors, bokeh and perfect focus.', '2013-09-16 05:38:17.000000', NULL, 1),
(7103282, 1082901, 153814, '<td valign="top">This was my favorite in the challenge. Great idea but next time paint your thumb please. Well done.</td>', 'This was my favorite in the challenge. Great idea but next time paint your thumb please. Well done.', '2013-09-16 08:51:17.000000', NULL, 1),
